def give_existing_refresh_tokens_an_expiry(apps, schema_editor):
    """Existing refresh tokens never expired. Rather than invalidating them,
    give each connection's current token a record that expires one full
    refresh-token lifetime after this migration runs."""
    from mcp_server.oauth_utils import decrypt_oauth_token

    connection_model = apps.get_model("mcp_server", "MCPConnection")
    family_model = apps.get_model("mcp_server", "MCPOAuthRefreshFamily")
    token_model = apps.get_model("mcp_server", "MCPOAuthRefreshToken")
    db = schema_editor.connection.alias
    ttl = int(getattr(settings, "MCP_OAUTH_REFRESH_TOKEN_TTL_SECONDS", 30 * 24 * 3600))
    expires_at = timezone.now() + timedelta(seconds=max(ttl, 1))
    rows = (
        connection_model._base_manager.using(db)
        .filter(deleted=False, oauth_refresh_token_encrypted__isnull=False)
        .exclude(oauth_refresh_token_encrypted="")
        .values_list("pk", "user_id", "oauth_refresh_token_encrypted")
    )
    for pk, user_id, token in rows.iterator(chunk_size=500):
        payload = decrypt_oauth_token(token)
        if (
            not payload
            or payload.get("type") != "mcp_refresh"
            or payload.get("user_id") != str(user_id)
        ):
            continue  # unusable today; nothing to preserve
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        if token_model.objects.using(db).filter(token_hash=token_hash).exists():
            continue
        family = family_model.objects.using(db).create(
            connection_id=pk, client_id=payload.get("client_id") or ""
        )
        token_model.objects.using(db).create(
            family=family, token_hash=token_hash, expires_at=expires_at
        )


